        "summary": "📣 On September 8th, within the framework of the Be active project, we held a conference where we presented our guidebook “Citizenship Education Toolkit” 📘✨.",
        "text_blocks": [
          "📣 On September 8th, within the framework of the Be active project, we held a conference where we presented our guidebook “Citizenship Education Toolkit” 📘✨.",
          "The guide book was created together with our partners 🇱🇹LVJUC and 🇷🇴 Asociația Empower Plus for young activists and youth leaders. It provides practical guidance on how to move from an idea to the implementation of an initiative – from team building, action planning, communication and promotion, to evaluation and measuring results. It’s a comprehensive tool designed to empower young people in taking their own civic actions. 🚀",
          "During the conference, we also presented other educational products and materials for young people to help them organize local initiatives, raise awareness, and encourage youth activism. 🌍✨",
          "The conference was not only an opportunity to explore the toolkit, but also to connect and have fun together – we wrapped it up with a karaoke and dance evening 💃🎤, combining skill development with activities that foster relationships and cooperation."
        ],
