    "desc_pl": "Wymiana młodzieżowa Erasmus+ łącząca 35 uczestników z 7 krajów w górskim rejonie Vatra Dornei w Rumunii. Skupiona na edukacji ekologicznej, ochronie bioróżnorodności, walce z marnotrawstwem zasobów i budowaniu międzynarodowego dialogu młodzieżowego.",
    "desc_en": "Erasmus+ Youth Exchange gathering 35 active participants from 7 European countries in Vatra Dornei, Romania. Dedicated to environmental literacy, biodiversity preservation, zero-waste practices and cross-border intercultural solidarity.",
