        "title": "#PLUGTREE+ Youth Exchange",
        "hero_img": "https://animusedu.com/wp-content/uploads/2026/09/726949550_36599849226326635_8358088394579047416_n-850x537.jpg",
        "images": [
          "https://animusedu.com/wp-content/uploads/2026/09/726949550_36599849226326635_8358088394579047416_n-850x537.jpg",
          "https://animusedu.com/wp-content/uploads/2026/09/I-had-the-most-amazing-Erasmus-experience-in-Vatra-Dornei-Romania-thanks-to-@thebelarusian-@-2-1024x576.jpg",
          "https://animusedu.com/wp-content/uploads/2026/09/I-had-the-most-amazing-Erasmus-experience-in-Vatra-Dornei-Romania-thanks-to-@thebelarusian-@-1-1024x576.jpg",
          "https://animusedu.com/wp-content/uploads/2026/09/I-had-the-most-amazing-Erasmus-experience-in-Vatra-Dornei-Romania-thanks-to-@thebelarusian-@-1024x576.jpg",
          "https://animusedu.com/wp-content/uploads/2026/09/726420774_858626907305812_1895414746423572290_n-1024x576.jpg"
        ],
        "summary": "We are pleased to announce that our youth activists had the opportunity to participate in#PLUGTREE+, an Erasmus+ Youth Exchange implemented between 14 and 20 June 2026 in Vatra Dornei, Romania, with the participation of 35 people from Romania, Poland, Lithuania, Latvia, Estonia, Greece and Türkiye.",
        "text_blocks": [
          "We are pleased to announce that our youth activists had the opportunity to participate in#PLUGTREE+, an Erasmus+ Youth Exchange implemented between 14 and 20 June 2026 in Vatra Dornei, Romania, with the participation of 35 people from Romania, Poland, Lithuania, Latvia, Estonia, Greece and Türkiye.",
          "The project brought together 28 young participants and 7 group leaders, including 14 young people with fewer opportunities, in an inclusive learning environment based on non-formal education, intercultural dialogue and peer cooperation.",
          "Project objectives and related activities",
          "Objective 1: Strengthening participants’ understanding and critical attitudes towards discrimination, stereotypes and social exclusion",
          "Objective 2: Enhancing the social inclusion and sense of belonging of 14 young people with fewer opportunities",
          "Objective 3: Increasing the capacity of the seven partner organisations to address discrimination and social exclusion through youth work",
          "Main project activities",
          "During the seven activity days, participants took part in:",
          "workshops addressing stereotypes, discrimination and exclusion;",
          "Human Library sessions based on personal experiences;",
          "media literacy and fake news activities;",
          "World Café discussions and Forum Theatre;",
          "intercultural learning and country presentations;",
          "Photovoice and digital storytelling workshops;",
          "the creation and presentation of short films;",
          "daily reflection and Youthpass activities;",
          "dissemination and follow-up planning.",
          "Through their participation in#PLUGTREE+, young people strengthened their competences in critical thinking, media literacy, communication, teamwork, leadership, digital creativity and intercultural cooperation.",
          "The project also contributed to:",
          "greater awareness of discrimination, stereotypes and social exclusion;",
          "increased empathy and openness towards cultural and social diversity;",
          "improved capacity to identify and challenge misinformation and discriminatory narratives;",
          "stronger participation and inclusion of young people with fewer opportunities;",
          "the creation of Photovoice stories, short films, testimonials and digital awareness materials;",
          "stronger cooperation among the seven partner organisations;",
          "the development of practical methods that can be reused in youth work and future Erasmus+ activities;",
          "the creation of a European network of young people and organisations committed to inclusion, dignity and respect for diversity.",
          "One of the main outputs of the project is the#PLUGTREE+ Toolkit of Inclusive Practices, which brings together methods, activities and practical resources that youth workers, educators and organisations can use to promote inclusion and combat discrimination.",
          "Access the#PLUGTREE+ Toolkit of Inclusive Practices:",
          "Watch the project video:",
          "#PLUGTREEplus#ErasmusPlus#YouthExchange#SocialInclusion#NonFormalEducation#YouthWork#InterculturalDialogue#CriticalThinking#MediaLiteracy#EuropeanYouth#ALT357",
          "The European Commission support for the production of this publication does not constitute an endorsement of the contents, which reflect the views only of the authors, and the National Agency and the Commission cannot be held responsible for any use which may be made of the information contained therein."
        ],
