        "summary": "At the Experiential Learning Congress 2025, the Animus Foundation had the opportunity to provide a dissemination activity as part of our commitment to innovative and impactful learning experiences.",
        "text_blocks": [
          "At the Experiential Learning Congress 2025, the Animus Foundation had the opportunity to provide a dissemination activity as part of our commitment to innovative and impactful learning experiences.",
          "We proudly introduced the CARE board game—part of the CARE: Climate Action Roleplay Experience project—to a global audience! Participants from around the world, including not only those from the EU but also from Turkey, Colombia, Canada, the United Kingdom, and South Africa, stepped into the roles of decision-makers, working together to protect a forest and its ecosystem while navigating real-world environmental challenges.",
          "The response? Inspiring!The game sparked engaging discussions, encouraged strategic thinking, and highlighted the importance of collaborative action in tackling climate issues. Seeing so many passionate individuals from diverse backgrounds come together to explore sustainable solutions was truly a powerful moment.",
          "A huge thank you to everyone who joined, played, and shared their insights."
        ],
