        "summary": "On October 3rd and 4th, as part of the final seminar for the “From Home to Home” project, we with our partners and experts held various workshops for our participants.",
        "text_blocks": [
          "On October 3rd and 4th, as part of the final seminar for the “From Home to Home” project, we with our partners and experts held various workshops for our participants.",
          "This was a good opportunity to share experiences and practical cases related to migrant adaptation.The workshops were conducted in both Polish and English, enabling an international group of participants to fully engage in knowledge exchange.",
          "Our speakers included leading experts in the field of youthwork: Michał Pietrzok, Magdalena Bogusławska, Kateryna Romanenko, Andrey Nikolow and others.All workshops focused on the topic of migrants and their adaptation, sparking lively discussions among participants .",
          "The seminar audience included directors of youth and cultural centers as well as stakeholders actively working in this area. This created a wonderful opportunity for networking and collaboration towards improving the psychological adaptation of migrants based on peer-to-peer approach in our communities.",
          "The project is co-funded by the European Union"
        ],
