        "url": "https://animusedu.com/index.php/2024/10/05/final-seminar-for-the-from-home-to-home-project/",
        "slug": "final-seminar-for-the-from-home-to-home-project",
        "date": "2024-10-05",
        "title": "Final Seminar for the From Home to Home Project",
        "hero_img": "https://animusedu.com/wp-content/uploads/2024/10/462188280_512739454879495_891720419695332337_n-1-850x638.jpg",
        "images": [
          "https://animusedu.com/wp-content/uploads/2024/10/462188280_512739454879495_891720419695332337_n-1-850x638.jpg",
          "https://animusedu.com/wp-content/uploads/2024/10/462043221_512739141546193_1995841913876336326_n-1-1024x768.jpg",
          "https://animusedu.com/wp-content/uploads/2024/10/462188280_512739454879495_891720419695332337_n-1024x768.jpg",
          "https://animusedu.com/wp-content/uploads/2024/10/462113476_512739421546165_3063406514495851219_n-1024x768.jpg",
          "https://animusedu.com/wp-content/uploads/2024/10/462128857_512739281546179_7037749321858978462_n-1024x768.jpg",
          "https://animusedu.com/wp-content/uploads/2024/10/462146945_512739211546186_3003869296671098482_n-1024x768.jpg",
          "https://animusedu.com/wp-content/uploads/2024/10/462054039_512739201546187_8281396692283241826_n-1024x768.jpg",
          "https://animusedu.com/wp-content/uploads/2024/10/462154377_512739134879527_5162507126050037794_n-1024x768.jpg"
        ],
        "summary": "On October 3rd, we hosted next part of our final seminar for the “From Home to Home” project.",
        "text_blocks": [
          "On October 3rd, we hosted next part of our final seminar for the “From Home to Home” project.",
          "The event took place in Warsaw’s most iconic building, Plac Kultury i Nauki, with more than 100 attendees.",
          "Together with our partners from theSituational Center Open Doorsand Epeka, we presented the key results of the project and introduced a model of the psychological adaptation of young migrants based on the peer-to-peer principle.",
          "Our project partners alsoshared their experiences and successes in organizing local activities with young migrants in local communities. The seminar provided an opportunity for participants from different countries and all over Poland to exchange experiences, ask questions, and discuss challenges related to working on the psychological adaptation of young migrants.",
          "The model for the psychological adaptation of young migrants based on the peer-to-peer principle was particularly well-received by directors of youth centers and youth workers, who actively support young migrants. This seminar highlighted not only the effectiveness of this approach but also the significant, positive impact it has had on the youth communities, fostering connections and encouraging collaboration among professionals in the field of youth work.",
          "The project is co-funded by the European Union"
        ],
        "h1s": [
          "Final Seminar for the From Home to Home Project"
        ],
