        "url": "https://animusedu.com/index.php/2024/06/02/training-course-in-bulgaria/",
        "slug": "training-course-in-bulgaria",
        "date": "2024-06-02",
        "title": "Training Course in Bulgaria",
        "hero_img": "https://animusedu.com/wp-content/uploads/2024/06/IMG_2159-850x638.jpg",
        "images": [
          "https://animusedu.com/wp-content/uploads/2024/06/IMG_2159-850x638.jpg"
        ],
        "summary": "From May 26 to June 01, the training course “Psychological Adaptation of Young Migrants on a Peer-to-Peer Basis” for youth leaders was held as part of the project “From Home to Home,” hosted by our partner organizationСитуационен Център Отворени Врати",
        "text_blocks": [
          "From May 26 to June 01, the training course “Psychological Adaptation of Young Migrants on a Peer-to-Peer Basis” for youth leaders was held as part of the project “From Home to Home,” hosted by our partner organizationСитуационен Център Отворени Врати",
          "The training course took place in the mountainous area of Bansko, Bulgaria, where 18 participants from Poland, Slovenia, and Bulgariaspent a productive week.During the training course:",
          "participants weretrained to work on the psychological adaptation of migrants on a peer-to-peer basis;",
          "analyzed the practical tools that are used for the psychological adaptation of young migrants;",
          "created more than 30 scenarios of local activities in the direction of art and culture, education, sports;",
          "participants were on a tour of the educational hub for Ukrainian migrants in Sofia;",
          "participants had the opportunity to attend the “last bell” event at a school for Ukrainian migrants.",
          "This training course not only equipped youth leaders and youth workers with essential skills for aiding young migrants but also fostered international cooperation.The participants returned to their countries inspired and ready to implement the knowledge and strategies they gained to support young migrants in their communities.",
          "We look forward to seeing the positive impact of their efforts and continuing our collaboration on such important initiatives.",
          "The project co-founded by the European Union."
        ],
        "h1s": [
          "Training Course in Bulgaria"
        ],
