        "title": "Jugger – Fight for a Healthy Lifestyle",
        "hero_img": "https://animusedu.com/wp-content/uploads/2024/10/ML5A2926-850x567.png",
        "images": [
          "https://animusedu.com/wp-content/uploads/2024/10/ML5A2926-850x567.png",
          "https://animusedu.com/wp-content/uploads/2024/10/IMG_20241019_115944975_HDR-1024x768.jpg",
          "https://animusedu.com/wp-content/uploads/2024/10/IMG_20241019_114526129_HDR-1024x768.jpg",
          "https://animusedu.com/wp-content/uploads/2024/10/IMG_20241019_114100155_HDR-1024x768.jpg"
        ],
        "summary": "On October 19, we gathered young students and adults in the scenic location of Wieleń Zaobrzański for the day of Jugger! 🌳💪",
        "text_blocks": [
          "On October 19, we gathered young students and adults in the scenic location of Wieleń Zaobrzański for the day of Jugger! 🌳💪",
          "Led by our active team member,@szymon.matyja.04, the activity, titled “Jugger – Fight for a Healthy Lifestyle”, was part of the@tinyhabitsforhepaproject, which promotes physical activity 🏃‍♂️🏃‍♀️ and encourages healthy habits among woman🌱.",
          "Szymon introduced participants to this unique, high-energy team sport that combines the intensity of rugby 🏉, the skill of fencing 🤺, and the strategy of basketball 🏀.",
          "Through this activity, participants not only got to experience an unconventional sport but also learned about the importance of mobility, the value of warming up 🔥, and the benefits of stretching 🧘.",
          "It was an inspiring way to foster a healthy, active lifestyle in a fun and engaging setting. 🎉",
          "Let’s keep moving, stay active, and build these tiny habits toward a healthier future! 🌟💚",
          "@deneyimselegitimmerkezi@aktyvistai@crossfitskopje",
          "The project is co-funded by the European Union 🇪🇺"
        ],
        "h1s": [
          "Jugger – Fight for a Healthy Lifestyle"
        ],
