        "url": "https://animusedu.com/index.php/2024/09/21/21-wrzesnia-odbyla-sie-joga-na-swiezym-powietrzu/",
        "slug": "21-wrzesnia-odbyla-sie-joga-na-swiezym-powietrzu",
        "date": "2024-09-21",
        "title": "21 Września Odbyła się Joga na Świeżym Powietrzu!",
        "hero_img": "https://animusedu.com/wp-content/uploads/2024/09/1-1-850x478.png",
        "images": [
          "https://animusedu.com/wp-content/uploads/2024/09/1-1-850x478.png",
          "https://animusedu.com/wp-content/uploads/2024/09/2-1024x576.png",
          "https://animusedu.com/wp-content/uploads/2024/09/3-1024x576.png",
          "https://animusedu.com/wp-content/uploads/2024/09/7-1024x576.png",
          "https://animusedu.com/wp-content/uploads/2024/09/4-1024x576.png",
          "https://animusedu.com/wp-content/uploads/2024/09/5-1024x576.png",
          "https://animusedu.com/wp-content/uploads/2024/09/6-1024x576.png"
        ],
        "summary": "Dziękujemy wszystkim, którzy dołączyli do nas w Parku Śląskim i spędzili poranek w ruchu oraz relaksie. Było naprawdę wspaniale widzieć tyle uśmiechniętych twarzy!",
        "text_blocks": [
          "Dziękujemy wszystkim, którzy dołączyli do nas w Parku Śląskim i spędzili poranek w ruchu oraz relaksie. Było naprawdę wspaniale widzieć tyle uśmiechniętych twarzy!",
          "Podczas zajęć uczestnicy mieli okazję wykonać różnorodne ćwiczenia, które pozwoliły nie tylko wzmocnić ciało, ale również wyciszyć umysł i zrelaksować się. To był idealny sposób na rozpoczęcie weekendu i naładowanie baterii pozytywną energią.",
          "Szczególne podziękowania kierujemy do naszej aktywistki -Tosia Drabik , która była inicjatorką tego wydarzenia.",
          "Cieszymy się, że w naszej społeczności są tak aktywne osoby, które nie tylko dbają o własne zdrowie, ale również inspirują innych do podejmowania zdrowych nawyków. Wspólnie udowadniamy, że nawet małe działania mogą prowadzić do wielkich zmian!",
          "To nie koniec – przed nami jeszcze wiele takich wydarzeń w ramach projektuTiny habits. Obserwujcie nas, aby nie przegapić kolejnych spotkań i aktywności."
        ],
        "h1s": [
          "21 Września Odbyła się Joga na Świeżym Powietrzu!"
        ],
