        "title": "COMRES - Final Conference",
        "hero_img": "https://animusedu.com/wp-content/uploads/2023/02/photo_2023-02-02_15-00-31-850x638.jpg",
        "images": [
          "https://animusedu.com/wp-content/uploads/2023/02/photo_2023-02-02_15-00-31-850x638.jpg",
          "https://animusedu.com/wp-content/uploads/2023/02/photo_2023-02-02_14-59-55-1024x768.jpg",
          "https://animusedu.com/wp-content/uploads/2023/02/photo_2023-02-02_15-00-31-1024x768.jpg",
          "https://animusedu.com/wp-content/uploads/2023/02/photo_2023-02-02_15-00-55-1024x768.jpg",
          "https://animusedu.com/wp-content/uploads/2023/02/photo_2023-02-02_15-00-17-1024x768.jpg",
          "https://animusedu.com/wp-content/uploads/2023/02/photo_2023-02-02_15-01-02-1024x995.jpg",
          "https://animusedu.com/wp-content/uploads/2023/02/photo_2023-02-02_15-01-09-1024x768.jpg",
          "https://animusedu.com/wp-content/uploads/2023/02/photo_2023-02-02_15-01-13-1024x768.jpg",
          "https://animusedu.com/wp-content/uploads/2023/02/photo_2023-02-02_15-01-21-1024x768.jpg",
          "https://animusedu.com/wp-content/uploads/2023/02/photo_2023-02-02_15-01-52-1024x768.jpg"
        ],
        "summary": "On 31 January our Final Conference took place within the framework of the project “COMRES – Developing community resilience through adult education”.",
        "text_blocks": [
          "On 31 January our Final Conference took place within the framework of the project “COMRES – Developing community resilience through adult education”.",
          "The conference was attended by representatives of local organizations, initiatives, NGOs, representatives of the educational sector, etc. And also our international partners of the project – Synergy Bulgaria and L ORMA SOCIETA SPORTIVA DILETTANTISTICA A RESPONSABILITA LIMITATA.",
          "During the conference, the following issues were covered:",
          "– Presentation of the Erasmus+ program.",
          "– Presentation of the project COMRES",
          "– Developing community resilience through adult education.",
          "– What is Resilience?",
          "– Presentation of the results of the Comres project.",
          "– Representation of local organizations involved in the project countries.",
          "– Workshops with representatives from each partner organization (Italy, Bulgaria, Poland).",
          "– Presentation of video materials from trainings",
          "Also, the partner organizations of the project had the opportunity to present their organization, their activities and directions.",
          "There was a panel discussion. Our partners and experts who worked on the project talked about resilience from different points of view and gave practical examples. They discussed such questions:",
          "– Support for refugees and migrants in Bulgaria. How to be more resilient in such a demanding environment?",
          "– What is resilience? Mental and physical health. Resilience in post-Covid times and in the modern realities of war.",
          "– “W zdrowym ciele zdrowy duch” or How to improve your mental health through sports?",
          "– Community building. And what can be done to build a stronger personal community?",
          "– Activists and volunteers who help refugees and migrants – they also need help. How to be more sustainable in this help? How to manage volunteers in the long term?",
          "– How to recognize that there is something wrong with mental health? What to do if you find that your mental state has worsened?",
          "– Digital readiness in the frame of resilience.",
          "We are pleased that representatives of the whole region took part in our conference. Our theme has been able to unite and attract different kinds of communities and different ages.",
          "This conference motivates us to continue our work with the topic of resilience in the community. We will continue to support various communities, local organizations and initiatives on a local level.",
          "Follow our news. See you again."
        ],
        "h1s": [
          "COMRES – Final Conference"
        ],
