        "summary": "On December 5, Animus Foundation held a Voluntary Gala in the City of Piekary Śląskie. The event was held as part of our project “Youth in Action!”.",
        "text_blocks": [
          "On December 5, Animus Foundation held a Voluntary Gala in the City of Piekary Śląskie. The event was held as part of our project “Youth in Action!”.",
          "An event of this type was held for the first time in this region and attracted the attention of a large number of young people.",
          "Together with local partners of the city of Piekary Śląskie, such as Młodzieżowy Dom Kultury nr. 2 Piekary Śląskie and Młodzieżowa Rada Miasta Piekary Śląskie, we are organized the nomination “Best Volunteer of the Year in Piekary Śląskie”.",
          "Young volunteers had the opportunity to be nominated for the competition. The competition took place and 13 best volunteers from the Piekary Śląskie were selected. The winners were awarded with certificates and gifts.",
          "We are glad that many famous people of the city visited our gala, such as: Mayor of the city – Sława Umińska-Duraj, Head of the city council – Tomasz Wesołowski, Сommander of the ZHP Piekary Śląskie troop – Grzegorz Ociepka , library director – Marcin Jurkowski, director of Młodzieżowy Dom Kultury nr. 2 – Dobrosława Egner, also representatives of local organizations, representatives of schools, etc.",
          "We are very glad that we managed to activate the topic of volunteering among young people, thanks to the “Youth in Action” project, which we are implementing.",
          "We also managed to interview the participants of the competition. They shared their volunteer experiences and tips for aspiring volunteers. Soon we will post them on our resources. Follow our news!",
          "#Volunteerneighbor  #Volunteeringintheneighborhood #startvoluntering #helpyourneighborhood #volunteering #neigborhood"
        ],
        "h1s": [
          "Best Volunteers in the City Piekary Śląskie"
        ],
