        "title": "Gliwice: City Game",
        "hero_img": "https://animusedu.com/wp-content/uploads/2023/02/photo_2023-02-08_09-42-04-850x478.jpg",
        "images": [
          "https://animusedu.com/wp-content/uploads/2023/02/photo_2023-02-08_09-42-04-850x478.jpg",
          "https://animusedu.com/wp-content/uploads/2023/02/photo_2023-02-08_09-41-48-1024x576.jpg",
          "https://animusedu.com/wp-content/uploads/2023/02/photo_2023-02-08_09-41-50-1024x576.jpg",
          "https://animusedu.com/wp-content/uploads/2023/02/photo_2023-02-08_09-41-54-1024x576.jpg"
        ],
        "summary": "On December 3rd, 2022, Animus Foundation held a city game in Gliwice as part of the project “Youth in Action!”.",
        "text_blocks": [
          "On December 3rd, 2022, Animus Foundation held a city game in Gliwice as part of the project “Youth in Action!”.",
          "Young people from schools in Gliwice had the opportunity to participate in a city game. At the beginning, participants gathered at the Dessau Square where the rules of the game were presented. Later, as part of the game, participants solved puzzles, recorded a short film promoting volunteering, helped maintain the cleanliness of the city by cleaning up a part of Chopin Park and feeding birds in winter.",
          "Participants were able to see interesting places in Gliwice because, in addition to Chopin Park and Dessau Square, they visited the Tężnie and the Gliwice Radio Station. In the end, participants received a gift in the form of a thermos and a sweet treat.",
          "#Volunteerneighbor  #Volunteeringintheneighborhood #startvoluntering #helpyourneighborhood #volunteering #neigborhood"
        ],
        "h1s": [
          "Gliwice: City Game"
        ],
