      "Studenci wzięli udział w inspirującym warsztacie tematycznym, kolejnych grach integracyjnych, a wieczór spędzili przy wspólnym grillu.",
      "Razem podsumowaliśmy zdobyte doświadczenia i nowe przyjaźnie powstałe w ciągu tych trzech dni. Ogromne podziękowania dla naszych zaangażowanych młodych liderów oraz wszystkich uczestników za stworzenie tak gościnnej przestrzeni dla nowych studentów międzynarodowych Uniwersytetu Opolskiego.",
      "Niech nadchodzący rok akademicki będzie pełen kolejnych wspólnych przygód!",
