      "Pierwszy dzień poświęcony był wzajemnemu poznawaniu się poprzez zabawy integracyjne i aktywności ice-breaker. Studenci z wielu krajów spotkali się, podzielili się pierwszymi wrażeniami i zaczęli budować przyjaźnie ponad granicami. Atmosfera pełna była energii, śmiechu i ciekawości – inspirujący początek, by poczuć się jak w domu w Opolu!",
