    "url": "https://animusedu.com/index.php/2025/09/03/training-course-for-youth-workers-and-teachers/",
    "slug": "training-course-for-youth-workers-and-teachers",
    "date": "2025-09-03",
    "title": "Training Course for Youth Workers and Teachers",
    "hero_img": "https://animusedu.com/wp-content/uploads/2025/09/photo_2025-09-03_12-30-56-1-850x638.jpg",
    "images": [
      "https://animusedu.com/wp-content/uploads/2025/09/photo_2025-09-03_12-30-56-1-850x638.jpg",
      "https://animusedu.com/wp-content/uploads/2025/09/Be-active-1086x1536-2-724x1024.png",
      "https://animusedu.com/wp-content/uploads/2025/09/photo_2025-09-03_12-30-56-2-1-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2025/09/photo_2025-09-03_12-30-56-1-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2025/09/photo_2025-09-03_12-30-55-1-1024x768.jpg"
    ],
    "summary": "🌍 28 of August in Piekary Śląskie, Poland in the framework of the Be Active project, we had the opportunity to organize training course for youth workers and teachers who are actively engaged in supporting and empowering young people.",
    "text_blocks": [
      "🌍 28 of August in Piekary Śląskie, Poland in the framework of the Be Active project, we had the opportunity to organize training course for youth workers and teachers who are actively engaged in supporting and empowering young people.",
      "During the training:🤓 youth workers and educators explored new and innovative methods of working with youth,🙌 exchanged their professional experiences,⚡️discussed the challenges and opportunities that educators face today.",
      "One of the highlights of the course was the presentation of the Citizenship Education Toolkit, developed together with our project partners. This resource provides practical approaches and tools for promoting active citizenship and civic education among young people.",
      "✨ Beyond learning and sharing, the training also served as a platform to build connections and strengthen future cooperation. Youth workers and educators worked together on ideas for follow-up initiatives, ensuring that the impact of this project will continue to grow.",
      "We are proud to contribute to fostering active citizenship and supporting those who guide the next generation. 🤝"
    ],
