    "summary": "✨ Podsumowanie naszej kampanii „Edukacja obywatelska” w ramach projektu Okulary Młodzieżowe ✨Przez ostatnie dni intensywnie pracowaliśmy nad kampanią społeczną, której celem było pokazanie, że edukacja obywatelska to coś więcej niż szkolne definicje. To realne życie, decyzje, relacje, odpowiedzialność i wpływ, jaki każdy z nas może mieć na swoje otoczenie.W ciągu 9 dni stworzyliśmy serię krótkich wideo oraz zestaw plakatów, które poruszały najważniejsze tematy związane z obywatelskością:",
    "text_blocks": [
      "✨ Podsumowanie naszej kampanii „Edukacja obywatelska” w ramach projektu Okulary Młodzieżowe ✨Przez ostatnie dni intensywnie pracowaliśmy nad kampanią społeczną, której celem było pokazanie, że edukacja obywatelska to coś więcej niż szkolne definicje. To realne życie, decyzje, relacje, odpowiedzialność i wpływ, jaki każdy z nas może mieć na swoje otoczenie.W ciągu 9 dni stworzyliśmy serię krótkich wideo oraz zestaw plakatów, które poruszały najważniejsze tematy związane z obywatelskością:",
      "🔹 Czym jest edukacja obywatelska?🔹 Obowiązki obywatelskie🔹 Jak działa władza lokalna?🔹 Młodzi i wybory🔹 Aktywność poza wyborami🔹 Obalanie mitów🔹 Działanie online🔹 Rozmowa bez hejtu🔹 „Ja jestem zmianą”",
      "🎬 Każdy dzień kampanii to osobne wideo, plakat i jedno jasne przesłanie:Zmiana zaczyna się od Ciebie. Obywatelskość to codzienność — Twoja, nasza, wspólna.Dziękujemy wszystkim młodym osobom za zaangażowanie i kreatywność podczas tworzenia treści!Przed nami kolejne działania i kolejne kampanie społeczne w ramach projektu Okulary Młodzieżowe. 👀💛",
      "🇪🇺 Projekt współfinansowany przez Unię Europejską."
    ],
