      "grach RPG, planszowych oraz retro-gamingu",
      "warsztatach tematycznych i prelekcjach prowadzonych przez pasjonatów",
      "spotkaniach i rozmowach w otwartej, przyjaznej przestrzeni dla młodych ludzi",
      "strefie wystawców z rękodziełem i gadżetami popkulturowymi",
      "Wydarzenie stworzyło przestrzeń do integracji, rozwijania zainteresowań i budowania lokalnej społeczności opartej na współpracy i twórczym działaniu. To dokładnie te wartości, które wspieramy w projekcie Okulary Młodzieżowe — oddolne inicjatywy młodzieży, ich pasje i aktywność obywatelską.",
      "Dziękujemy Klubowi Kregulec oraz wszystkim młodym uczestnikom za zaangażowanie, atmosferę i fantastyczną energię!"
