    "hero_img": "https://animusedu.com/wp-content/uploads/2025/12/556360085_777863461700425_9180504503078992900_n-1-768x576.jpg",
    "images": [],
    "summary": "🔐 Podsumowanie kampanii „Bezpieczny internet” w ramach projektu Okulary Młodzieżowe 🔐Przez ostatnie dni skupialiśmy się na jednym z najważniejszych tematów współczesności — bezpieczeństwie w internecie. Chcieliśmy pokazać młodym osobom, że cyfrowy świat daje ogromne możliwości, ale wymaga świadomości, ostrożności i odpowiedzialności.W ramach kampanii przygotowaliśmy serię krótkich filmów edukacyjnych oraz plakaty, które w prosty sposób tłumaczyły, jak dbać o siebie online.Oto, co udało nam się poruszyć:",
    "text_blocks": [
      "🔐 Podsumowanie kampanii „Bezpieczny internet” w ramach projektu Okulary Młodzieżowe 🔐Przez ostatnie dni skupialiśmy się na jednym z najważniejszych tematów współczesności — bezpieczeństwie w internecie. Chcieliśmy pokazać młodym osobom, że cyfrowy świat daje ogromne możliwości, ale wymaga świadomości, ostrożności i odpowiedzialności.W ramach kampanii przygotowaliśmy serię krótkich filmów edukacyjnych oraz plakaty, które w prosty sposób tłumaczyły, jak dbać o siebie online.Oto, co udało nam się poruszyć:",
      "🔹 Czym jest bezpieczny internet?🔹 Silne hasła🔹 Fake newsy i manipulacje🔹 Cyfrowy ślad🔹 Hejt i toksyczność w sieci🔹 Prawa autorskie🔹 Algorytmy i kontrola nad ekranem",
      "🎬 Każdy dzień kampanii to osobne wideo, plakat i jasny przekaz:Internet może być bezpiecznym miejscem — jeśli korzystamy z niego świadomie.Dziękujemy wszystkim młodym osobom za udział i kreatywność podczas tworzenia materiałów!Kampania „Bezpieczny internet” to kolejny krok w budowaniu cyfrowej odpowiedzialności w ramach projektu Okulary Młodzieżowe. 🛡✨",
      "🇪🇺 Projekt współfinansowany przez Unię Europejską."
    ],
