    "date": "2025-06-24",
    "title": "Final Words From Youth Starters",
    "hero_img": "https://animusedu.com/wp-content/uploads/2025/06/511269952_700753156078123_4889679240292231115_n.jpg",
    "images": [
      "https://animusedu.com/wp-content/uploads/2025/06/511269952_700753156078123_4889679240292231115_n.jpg",
      "https://animusedu.com/wp-content/uploads/2025/06/510768942_700753389411433_8187862688986856508_n-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2025/06/511139827_700753339411438_5025766379253344025_n-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2025/06/511265304_700753212744784_7508669034953426277_n-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2025/06/511125241_700753476078091_626111920759134624_n-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2025/06/511123556_700753236078115_7620358940837995930_n-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2025/06/511276500_700753172744788_6802802176047048388_n-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2025/06/510739263_700753302744775_6307497118371421118_n-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2025/06/511159290_700753462744759_2354597731138787988_n-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2025/06/510572482_700753372744768_259485953169003328_n-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2025/06/511260175_700753419411430_786623133692176703_n-1024x768.jpg"
    ],
    "summary": "Our youth exchange “Youth Starter – Don’t be scary to BE discovery” has come to an end — but the memories, lessons, and connections will stay with us for a long time.",
    "text_blocks": [
      "Our youth exchange “Youth Starter – Don’t be scary to BE discovery” has come to an end — but the memories, lessons, and connections will stay with us for a long time.",
      "More than 7 days we spent together. Young people from Poland, Georgia, Ukraineand Sloveniaexplored mental well-being, work-life balance, and the power of youth voices. We learned how to take care of ourselves, how to support each other, and how to turn ideas into action.",
      "From team-building and expert workshops to hikes, creative campaigns, and meaningful reflections — this journey was all about growth, courage, and community. Thank you to everyone who made it possible!",
      "Until next time, stay bold and kind. Don’t be scared to be discovery.",
      "The project is co-funded by the European Union",
      "• იყავი აქტიური, იყავი ჯანმრთელი • Be Active, Be Healthy",
      "Mladinski center Postojna / MCP",
      "NGO “Initiative Youth Network” ГО “Мережа Ініціативної Молоді”"
    ],
