    "summary": "On April 30th, we gathered for a fun and engaging board game evening as part of the Be Active project in Zebrzydowice!",
    "text_blocks": [
      "On April 30th, we gathered for a fun and engaging board game evening as part of the Be Active project in Zebrzydowice!",
      "This local activity brought together young people, youth council members, and community activists in a relaxed and friendly atmosphere — encouraging interaction, teamwork, and meaningful conversations.",
      "While the games were fun and competitive, the evening also reflected the deeper goals of the project: building connections, practicing communication, and promoting youth participation through informal and inclusive methods.",
      "Moments like these remind us that active citizenship doesn’t always have to be serious — it can be playful, social, and deeply impactful.",
      "Thanks to everyone who joined us in turning games into a space for community building and civic reflection!",
      "The project is co-funded by the European Union"
    ],
