    "text_blocks": [
      "On April 28th, the Animus Foundation organized an interactive quest for young people in Zebrzydowice!",
      "This local activity was part of the Be Active project, which aims to promote Citizenship Education and strengthen youth engagement at the local level.",
      "During the quest — designed as a dynamic city game — young activists and members of youth councils worked in teams to solve puzzles and find clues.Their final mission was to create an inspiring motivational slogan: “Twoje słowa inspirują realne działania” (“Your words inspire real actions”), perfectly reflecting the spirit of the project.",
      "The activity encouraged teamwork, critical thinking, and creativity. Participants first collaborated in small groups and later united as one big team to complete the final challenge together.",
      "We are proud to see so much energy, passion, and commitment from the young people who are ready to make a real impact in their communities!",
      "The project is co-funded by the European Union"
    ],
    "h1s": [
      "Interactive Quest for Youth in Zebrzydowice"
    ],
