    "url": "https://animusedu.com/index.php/2025/04/18/we-are-excited-to-share-the-citizenship-education-toolkit/",
    "slug": "we-are-excited-to-share-the-citizenship-education-toolkit",
    "date": "2025-04-18",
    "title": "We are excited to share the Citizenship Education Toolkit!",
    "hero_img": "https://animusedu.com/wp-content/uploads/2025/06/Be-active-850x1202.png",
    "images": [
      "https://animusedu.com/wp-content/uploads/2025/06/Be-active-850x1202.png"
    ],
    "summary": "🎉 As part of the Be Active project, together with our partners, we have created a comprehensive Citizenship Education Toolkit — a practical and inspiring resource designed for facilitators, youth workers, educators, and young leaders across Europe.",
    "text_blocks": [
      "🎉 As part of the Be Active project, together with our partners, we have created a comprehensive Citizenship Education Toolkit — a practical and inspiring resource designed for facilitators, youth workers, educators, and young leaders across Europe.",
      "🧩 The Toolkit includes:✅ Clear explanations of key civic education concepts✅ Modular activities and session plans on youth participation, democracy, advocacy, and more✅ Ready-to-use templates and planning tools✅ Real-life youth initiatives and reflection exercises to spark inspiration✅ Guidance on how to identify community needs and run meaningful local actions",
      "Whether you’re running a workshop, preparing a youth training, or guiding young changemakers — this Toolkit is for you!",
      "💡 Dive into modules such as:🔹 I am a Citizen🔹 Youth Participation🔹 Democracy in Practice🔹 Creating and Running Initiatives🔹 Communication and Advocacy🔹 Resources and Inspiration",
      "👉You can find the Toolkit here",
      "Let’s empower youth to be active, informed, and engaged citizens! 🌍💬"
    ],
    "h1s": [
      "We are excited to share the Citizenship Education Toolkit!"
    ],
