    "url": "https://animusedu.com/index.php/2025/02/05/our-activists-are-taking-action-for-neurodiversity/",
    "slug": "our-activists-are-taking-action-for-neurodiversity",
    "date": "2025-02-05",
    "title": "Our Activists are Taking Action for Neurodiversity!",
    "hero_img": "https://animusedu.com/wp-content/uploads/2025/02/IMG_20250203_221434-850x638.jpg",
    "images": [
      "https://animusedu.com/wp-content/uploads/2025/02/IMG_20250203_221434-850x638.jpg",
      "https://animusedu.com/wp-content/uploads/2025/02/IMG-20250131-WA0005-768x1024.jpg",
      "https://animusedu.com/wp-content/uploads/2025/02/IMG-20250203-WA0001-771x1024.jpg",
      "https://animusedu.com/wp-content/uploads/2025/02/IMG-20250203-WA0025-771x1024.jpg"
    ],
    "summary": "From January 26th to February 2nd, our dedicated youth leaders are participating in the “Action for Sustainable Partnerships in Neurodiversity” training course in Roquetas de Mar, Spain 🇪🇦☀️. This initiative brings together professionals and volunteers from across Europe to strengthen support systems for neurodivergent youth 🧠💡.",
    "text_blocks": [
      "From January 26th to February 2nd, our dedicated youth leaders are participating in the “Action for Sustainable Partnerships in Neurodiversity” training course in Roquetas de Mar, Spain 🇪🇦☀️. This initiative brings together professionals and volunteers from across Europe to strengthen support systems for neurodivergent youth 🧠💡.",
      "📌 What’s happening at the training course?🔹 Deep dive into neurodiversity – from theory to real-life experiences.🔹 Sessions on science, needs, and terms of neurodiversity to build inclusive approaches.🔹 Workshops on project management, digitalization of youth work, and Erasmus+ opportunities.🔹 Networking and partnership-building to create new youth exchange projects.",
      "This training course empowers participants with knowledge and tools to advocate, support, and take action in education, social integration, and personal development of neurodivergent youth. Also our participants developed an idea for a new youth exchange project, inspired by the training. We’re happy that this initiative has become a space for creativity and the birth of new projects and excited to see the impact they will bring back to their communities! 💛🚀"
    ],
    "h1s": [
      "Our Activists are Taking Action for Neurodiversity!"
    ],
