    "url": "https://animusedu.com/index.php/2024/12/16/model-of-psychological-adaptation-of-young-migrants-in-4-languages/",
    "slug": "model-of-psychological-adaptation-of-young-migrants-in-4-languages",
    "date": "2024-12-16",
    "title": "Model of Psychological Adaptation of Young Migrants – in 4 Languages!",
    "hero_img": "https://animusedu.com/wp-content/uploads/2025/04/Дизайн-без-назви-2-850x1063.png",
    "images": [
      "https://animusedu.com/wp-content/uploads/2025/04/Дизайн-без-назви-2-850x1063.png"
    ],
    "summary": "📢 Great news! The MODEL OF PSYCHOLOGICAL ADAPTATION OF YOUNG MIGRANTS BASED ON THE PEER-TO-PEER PRINCIPLE is now available in English, Polish, Bulgarian, and Slovenian. This expansion makes our methodology even more accessible to youth workers, educators, and organizations supporting young migrants.",
    "text_blocks": [
      "📢 Great news! The MODEL OF PSYCHOLOGICAL ADAPTATION OF YOUNG MIGRANTS BASED ON THE PEER-TO-PEER PRINCIPLE is now available in English, Polish, Bulgarian, and Slovenian. This expansion makes our methodology even more accessible to youth workers, educators, and organizations supporting young migrants.",
      "Developed as part of the From Home to Home project by Animus Foundation, in partnership with Situational Center Open Doors 🇧🇬 and Epeka 🇸🇮, this manual provides 37 structured modules covering:",
      "🎨 Art – Encouraging self-expression and communication.⚽️ Sport – Fostering inclusion beyond language barriers.📚 Education – Helping young migrants navigate their new environment.",
      "💡 Why is this important?✅ Supports the integration of young migrants into local communities.✅ Creates a safe space for personal growth and communication.✅ Empowers youth to take an active role in their adaptation process.✅ Engages local organizations, youth centers, and cultural institutions in fostering youth participation.",
      "📖 Access the manual in your preferred language:",
      "🔹 English🖥 Interactive guide: https://view.genially.com/664f4199286efa0015a5921d/presentation-model-of-psychological-adaptation-eng📄 PDF: https://drive.google.com/file/d/1R5LE3R57PY8-Rpmk2h8qBhFXlpoMkt4S/view?usp=sharing",
      "🔹 Polish🖥 Interactive guide: https://view.genially.com/679a211b7a38558f8eb59800/presentation-pl-model-of-psychological-adaptation📄 PDF: https://drive.google.com/file/d/1BIN84pkDW86i0ukEPJGzJllOdRF2J5X1/view?usp=sharing",
      "🔹 Bulgarian🖥 Interactive guide: https://view.genially.com/679b25ac914fe2b74185db9e/presentation-bg-model-of-psychological-adaptation-eng📄 PDF: https://drive.google.com/file/d/1BoU-mDvqy-ct2-7wMQU51qcwPeihIyV8/view?usp=sharing",
      "🔹 Slovenian🖥 Interactive guide: https://view.genially.com/679b259b848a25da6f320404/presentation-sl-model-of-psychological-adaptation-eng📄 PDF: https://drive.google.com/file/d/1nljnI1V1qamNx2HCLM8Th7unqdduGuio/view?usp=sharing",
      "📚 All printed versions are available upon request.",
      "Project co-funded by the European Union 🇪🇺"
    ],
