      "On October 29 Animus Foundation held a local activities at a school featuring the CARE board game, developed as part of the CARE: Climate Action Roleplay Experience project.",
      "Today we organized two sessions, and we are delighted with the level of interest and enthusiasm shown by the young participants! This engaging and educational game brings awareness to the impact of climate change on nature and humanity, showing players both the positive and negative effects of theiractions on the environment.",
