    "hero_img": "https://animusedu.com/wp-content/uploads/2025/01/464579072_529577483195692_1350943267854242192_n-850x1133.jpg",
    "images": [
      "https://animusedu.com/wp-content/uploads/2025/01/464579072_529577483195692_1350943267854242192_n-850x1133.jpg",
      "https://animusedu.com/wp-content/uploads/2025/01/464579072_529577483195692_1350943267854242192_n-768x1024.jpg",
      "https://animusedu.com/wp-content/uploads/2025/01/464787233_529577516529022_5940150381648385504_n-582x1024.jpg",
      "https://animusedu.com/wp-content/uploads/2025/01/464871848_529577479862359_1960834356548371158_n-581x1024.jpg"
    ],
    "summary": "On October 26, 2024, in Szczecin, as part of theTiny habitsproject, our activist Daria Górska led a workshop focused on exercises for balance and stability. These gentle yet effective exercises strengthen core muscles over time, supporting a healthier, more stable body and encouraging active living in our everyday lives.",
    "text_blocks": [
      "On October 26, 2024, in Szczecin, as part of theTiny habitsproject, our activist Daria Górska led a workshop focused on exercises for balance and stability. These gentle yet effective exercises strengthen core muscles over time, supporting a healthier, more stable body and encouraging active living in our everyday lives.",
      "During the session, participants also took part in an open discussion on ways to integrate small, achievable physical activities into their dailyroutines.",
      "The workshop was open to all, welcoming anyone ready to explore new ways to stay active and healthy. Thank you to everyone who joined us in embracing these tiny yet powerful steps towards a healthier lifestyle!",
      "The project is co-funded by the European Union"
    ],
