    "images": [
      "https://animusedu.com/wp-content/uploads/2024/06/IMG_2491-850x638.jpeg",
      "https://animusedu.com/wp-content/uploads/2024/06/IMG_2492-1024x768.jpeg",
      "https://animusedu.com/wp-content/uploads/2024/06/IMG_2493-1024x768.jpeg",
      "https://animusedu.com/wp-content/uploads/2024/06/IMG_2494-1024x461.jpeg",
      "https://animusedu.com/wp-content/uploads/2024/06/IMG_2495-1024x768.jpeg"
    ],
    "summary": "From June 8th to 14th, our team participating in a training course in Zagreb, Croatia 🇭🇷, as part of the CARE project. ☘️Our partners, Interaktiva, are the hosting organization, and ASNU – Associazione Scienze Naturali Unite is the leading organization. 🤝During this training course, participants learn about the creation of educational games, explore the causes and consequences of climate change, and delve into the complexities of this topic. 🎲 They also learn how to conduct debriefings and understand their importance, as well as how to facilitate educational games.👀",
    "text_blocks": [
      "From June 8th to 14th, our team participating in a training course in Zagreb, Croatia 🇭🇷, as part of the CARE project. ☘️Our partners, Interaktiva, are the hosting organization, and ASNU – Associazione Scienze Naturali Unite is the leading organization. 🤝During this training course, participants learn about the creation of educational games, explore the causes and consequences of climate change, and delve into the complexities of this topic. 🎲 They also learn how to conduct debriefings and understand their importance, as well as how to facilitate educational games.👀",
      "🎯The primary goal of the training is to equip youth workers with the skills to conduct the educational game developed under the CARE project and to assist them in planning local events where they will implement this game.🙌",
      "Stay tuned for updates and insights from our CARE project!☘️The project co-founded by the European Union🇪🇺"
    ],
    "h1s": [
      "CARE: Training Course in Zagreb"
    ],
