    "title": "Conference: Akcja Reakcja - Nowa Edukacja",
    "hero_img": "https://animusedu.com/wp-content/uploads/2024/06/photo_2024-06-12_13-03-00-850x383.jpg",
    "images": [
      "https://animusedu.com/wp-content/uploads/2024/06/photo_2024-06-12_13-03-00-850x383.jpg",
      "https://animusedu.com/wp-content/uploads/2024/06/photo_2024-06-12_13-33-31-768x1024.jpg",
      "https://animusedu.com/wp-content/uploads/2024/06/photo_2024-06-12_13-03-00-3-768x1024.jpg",
      "https://animusedu.com/wp-content/uploads/2024/06/photo_2024-06-12_13-03-00-2-1024x462.jpg"
    ],
    "summary": "On June 11th, the “Akcja Reakcja – Nowa Edukacja” conference took place in Mikołów, where our educational expert, Kateryna Romanenko, conducted a session for young people on the topic of self-assessment of civic competence. The session was an inspiring and interactive experience, providing valuable insights and practical tools for the participants to evaluate and enhance their civic skills.",
    "text_blocks": [
      "On June 11th, the “Akcja Reakcja – Nowa Edukacja” conference took place in Mikołów, where our educational expert, Kateryna Romanenko, conducted a session for young people on the topic of self-assessment of civic competence. The session was an inspiring and interactive experience, providing valuable insights and practical tools for the participants to evaluate and enhance their civic skills.",
      "During the session, Kateryna shared information and tools to help young individuals understand their roles as active citizens and how they can contribute positively to their communities. Participants engaged in dynamic discussions, group activities, and reflective exercises that encouraged them to think critically about their civic responsibilities and personal growth.",
      "We are thrilled to see such enthusiasm and dedication from the young attendees, and we look forward to continuing our work in empowering the next generation of informed and active citizens. Stay tuned for more updates and exciting events!"
    ],
    "h1s": [
      "Conference: Akcja Reakcja – Nowa Edukacja"
    ],
