    "title": "Playtest of our Roleplay Game",
    "hero_img": "https://animusedu.com/wp-content/uploads/2024/06/photo_2024-06-04_10-26-41-2-850x572.jpg",
    "images": [
      "https://animusedu.com/wp-content/uploads/2024/06/photo_2024-06-04_10-26-41-2-850x572.jpg",
      "https://animusedu.com/wp-content/uploads/2024/06/photo_2024-06-04_10-26-41-3-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2024/06/photo_2024-06-04_10-26-41-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2024/06/photo_2024-06-04_10-12-31-2-462x1024.jpg",
      "https://animusedu.com/wp-content/uploads/2024/06/photo_2024-06-04_10-12-31-1024x462.jpg"
    ],
    "summary": "On March 15, we held a playtest of our Role-Playing Game, which is being developed as part of the “CARE: Climate Action Role-Playing Experience” project, in collaboration with our partners from ItalyASNU – Associazione Scienze Naturali Uniteand CroatiaInteraktiva.",
    "text_blocks": [
      "On March 15, we held a playtest of our Role-Playing Game, which is being developed as part of the “CARE: Climate Action Role-Playing Experience” project, in collaboration with our partners from ItalyASNU – Associazione Scienze Naturali Uniteand CroatiaInteraktiva.",
      "The game is designed to dive participants in environmental dynamics, encouraging them to reflect on essential questions such as what provides us with oxygen, clean water, and food.",
      "By taking onvarious roles, players not only have fun but also gain valuable insights into environmental issues and are motivated to take action to protect our planet in their everyday lives.",
      "We are thrilled with the positive feedback and insightful suggestions we received during the playtest.",
      "This was a crucial step in refining our game to ensure it effectively educates and inspires players.",
      "Stay tuned for more updates as we continue to develop this exciting game!",
      "The project co-founded by the European Union."
    ],
    "h1s": [
      "Playtest of our Roleplay Game"
    ],
