    "summary": "From January 11-12, 2024, ANIMUS Foundation proudly joined forces with our partners from Sloveniaand Bulgariaat the kick-off meeting in Slovenia, marking the inception of the transformative “From Home to Home” project.",
    "text_blocks": [
      "From January 11-12, 2024, ANIMUS Foundation proudly joined forces with our partners from Sloveniaand Bulgariaat the kick-off meeting in Slovenia, marking the inception of the transformative “From Home to Home” project.",
      "Key Highlights from the Kickoff Meeting:",
      "– Discussed dates for upcoming global meetings.",
      "–Finalized partnership agreement.",
      "– Outlined steps for comprehensive research on migrant challenges.",
      "– Discussed model of psychological adaptation of young migrants on the basis on the peer-to-peer principles.",
      "– Designated coordinators from each partner organization who will be responsible for the project.",
      "Together with our partnersEpeka SloveniaandСитуационен Център Отворени Вратиwe are passionate about catalyzing positive change, focusing on the psychological adaptation of young migrants through peer-to-peer learning principles. Stay tuned for updates as we turn the collective vision of “From Home to Home” into a reality. Together, we’re making a difference!"
    ],
