    "images": [
      "https://animusedu.com/wp-content/uploads/2023/12/photo_2023-12-07_20-07-10-850x638.jpg",
      "https://animusedu.com/wp-content/uploads/2023/12/photo_2023-12-07_20-07-08-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2023/12/photo_2023-12-07_20-07-09-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2023/12/385493261_1528012998021255_6911002616115090105_n-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2023/12/photo_2023-12-07_20-07-10-1024x768.jpg"
    ],
    "summary": "On December 5th, Animus Foundation held a memorable Volunteer concert in the city Piekary-Śląskie.",
    "text_blocks": [
      "On December 5th, Animus Foundation held a memorable Volunteer concert in the city Piekary-Śląskie.",
      "Embracing the spirit of innovation, we aimed to cultivate new traditions. This marked the second installment of such an event in the city, drawing an enthusiastic crowd of vibrant young individuals.",
      "In collaboration with esteemed local partnersMDK2 Piekary ŚląskieandMłodzieżowa Rada Miasta Piekary Śląskie, we proudly organized the “Best Volunteer of the Year in PiekaryŚląskie” nomination.",
      "Aspiring young volunteers eagerly participated, event for the coveted title. The event unfolded seamlessly, leading to the selection of the top 10 volunteers from Piekary Śląskie. Each volunteer was honored with certificates and thoughtful gifts.",
      "We extend a heartfelt invitation to the vibrant energy of new young volunteers. In their endeavors, they not only fortify the bonds within our community but also embrace the opportunity to explore diverse roles.With optimism we aspire to celebrate and reward the contributions of these fresh faces in the coming year. Together, let’s weave a tapestry of shared experiences and collective growth."
    ],
