    "url": "https://animusedu.com/index.php/2023/10/21/kicking-off-the-beactive-project-animus-team-gathers-in-lithuania/",
    "slug": "kicking-off-the-beactive-project-animus-team-gathers-in-lithuania",
    "date": "2023-10-21",
    "title": "Kicking Off the BeActive Project: ANIMUS Team Gathers in Lithuania",
    "hero_img": "https://animusedu.com/wp-content/uploads/2023/10/photo_2023-10-21_13-12-35-850x638.jpg",
    "images": [
      "https://animusedu.com/wp-content/uploads/2023/10/photo_2023-10-21_13-12-35-850x638.jpg",
      "https://animusedu.com/wp-content/uploads/2023/10/photo_2023-10-21_13-13-05-1024x767.jpg",
      "https://animusedu.com/wp-content/uploads/2023/10/photo_2023-10-21_13-12-57-768x1024.jpg",
      "https://animusedu.com/wp-content/uploads/2023/10/photo_2023-10-21_13-12-37-1024x768.jpg"
    ],
    "summary": "On October 19-20, 2023, ANIMUS Foundation was delighted to join our partners from Lithuania and Romania at the kick-off meeting of the BeActive project in Lithuania, officially starting our collaborative journey to promote active youth engagement, citizenship and volunteering.",
    "text_blocks": [
      "On October 19-20, 2023, ANIMUS Foundation was delighted to join our partners from Lithuania and Romania at the kick-off meeting of the BeActive project in Lithuania, officially starting our collaborative journey to promote active youth engagement, citizenship and volunteering.",
      "As the BeActive project aims to promote youth participation, citizenship and volunteering, this meeting was an important step in the right direction. The main points of the meeting were the following:",
      "Distribution of Responsibilities",
      "Preparations for Youth Exchange in Poland",
      "Agreement on Administrative Issues",
      "We also had the opportunity to get to know the local community. We visited a municipality and a Linkuva Youth & Children Centre, in order to better understand the local context and to establish closer ties with the communities with which they will have to work.",
      "The BeActive project is designed to span two transformative years of fruitful work. We extend our sincere gratitude to our partners. Together, we are poised to create a lasting impact, nurturing a bright future for youth engagement, citizenship and volunteering."
    ],
    "h1s": [
      "Kicking Off the BeActive Project: ANIMUS Team Gathers in Lithuania"
    ],
