    "hero_img": "https://animusedu.com/wp-content/uploads/2023/03/photo_2023-03-20_19-33-07-850x638.jpg",
    "images": [
      "https://animusedu.com/wp-content/uploads/2023/03/photo_2023-03-20_19-33-07-850x638.jpg",
      "https://animusedu.com/wp-content/uploads/2023/03/photo_2023-03-20_19-33-04-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2023/03/photo_2023-03-20_19-33-08-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2023/03/photo_2023-03-20_19-33-02-1024x768.jpg"
    ],
    "summary": "The final administrative meeting for “Youth in Action” project was a huge success! We got to share the results of our hard work and experiences with our partnersLVJUCandCesta rozvojein Brno on March 10-11. We were so excited to see all of our partners in person again!",
    "text_blocks": [
      "The final administrative meeting for “Youth in Action” project was a huge success! We got to share the results of our hard work and experiences with our partnersLVJUCandCesta rozvojein Brno on March 10-11. We were so excited to see all of our partners in person again!",
      "During the meeting, we presented what we achieved in the project and talked about how we overcame challenges. It was really interesting to hear about how different partners approached the project and how we all worked together to reach our common goal.",
      "After the presentations, we discussed how we could work together on future volunteering projects, and it was amazing to brainstorm ideas and share our visions! During this project, we gained a lot of experience in project management, communication, and teamwork. We learned from each other, and the final administrative meeting was a great chance to reflect on our growth and progress.",
      "Overall, the meeting was an incredible experience, and we were all thrilled to see each other in person and celebrate the success of the project. We left feeling inspired and motivated for our next endeavors, and we can’t wait to continue our partnership and make a positive impact in our communities!",
      "#Volunteerneighbor  #Volunteeringintheneighborhood #startvoluntering #helpyourneighborhood #volunteering #neigborhood"
    ],
