    "slug": "progress-of-the-project-youth-say-green-deal",
    "date": "2023-03-12",
    "title": "Progress of the Project “Youth Say - Green Deal”",
    "hero_img": "https://animusedu.com/wp-content/uploads/2023/03/photo_2023-03-21_10-12-58-850x638.jpg",
    "images": [
      "https://animusedu.com/wp-content/uploads/2023/03/photo_2023-03-21_10-12-58-850x638.jpg",
      "https://animusedu.com/wp-content/uploads/2023/03/photo_2023-03-21_09-57-55-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2023/03/photo_2023-03-21_09-57-59-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2023/03/photo_2023-03-21_09-58-04-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2023/03/photo_2023-03-21_09-58-09-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2023/03/photo_2023-03-21_09-58-13-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2023/03/photo_2023-03-21_10-12-49-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2023/03/photo_2023-03-21_10-12-52-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2023/03/photo_2023-03-21_10-12-54-1024x768.jpg"
    ],
    "summary": "Being in the middle of our project, we at Fundacja Animus Centrum Edukacyjno-Szkoleniowe are delighted with the progress we have made so far.",
    "text_blocks": [
      "Being in the middle of our project, we at Fundacja Animus Centrum Edukacyjno-Szkoleniowe are delighted with the progress we have made so far.",
      "Our activities include a number of workshops, seminars and lectures on various topics related to the environment. We also held intercultural evenings where we celebrated our diversity through music, food and other cultural traditions.",
      "One of our most memorable events so far was a walk and talk in the woods near Buda Glogowska, where the project takes place. During the walk participants discussed and shared their experiences about local and global environmental issues of our time and tried to find solutions together.",
      "Overall, we are pleased with the progress we have made in the project to date. The participants actively participated in the project and were eager to learn and share their experiences. We still have much to do in the second half of the project, but we are confident that together we can have a positive impact on the environment."
    ],
    "h1s": [
      "Progress of the Project “Youth Say – Green Deal”"
    ],
