    "slug": "meeting-with-the-mayor-launching-a-new-action-plan",
    "date": "2022-11-21",
    "title": "Meeting with the Mayor: Launching a New Action Plan",
    "hero_img": "https://animusedu.com/wp-content/uploads/2023/02/photo_2023-02-08_12-20-57-850x638.jpg",
    "images": [
      "https://animusedu.com/wp-content/uploads/2023/02/photo_2023-02-08_12-20-57-850x638.jpg",
      "https://animusedu.com/wp-content/uploads/2023/02/photo_2023-02-08_12-19-46-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2023/02/photo_2023-02-08_12-19-29-768x1024.jpg",
      "https://animusedu.com/wp-content/uploads/2023/02/photo_2023-02-08_12-19-22-1024x768.jpg"
    ],
    "summary": "On November 21, 2022, Animus Foundation organized an important meeting with Mrs. Magdalena Czarnecka, Deputy Mayor at the Pszczyna Commune Office.",
    "text_blocks": [
      "On November 21, 2022, Animus Foundation organized an important meeting with Mrs. Magdalena Czarnecka, Deputy Mayor at the Pszczyna Commune Office.",
      "Young people from Pszczyna had the opportunity to tell the Deputy Mayor about their Action Plan, which they want to implement in the city. The aim of their social campaign is to make young people aware of the negative effects of alcoholism by cleaning selected places in the city. It was during the Youth in Action youth exchange that young people from Pszczyna created this plan and now they have a chance to implement it.",
      "Together, we can change the situation!",
      "#Volunteerneighbor  #Volunteeringintheneighborhood #startvoluntering #helpyourneighborhood #volunteering #neigborhood"
    ],
