    "date": "2022-11-11",
    "title": "Volunteer Podcasts from the Source",
    "hero_img": "https://animusedu.com/wp-content/uploads/2022/09/photo_2023-02-07_20-20-16-850x638.jpg",
    "images": [
      "https://animusedu.com/wp-content/uploads/2022/09/photo_2023-02-07_20-20-16-850x638.jpg",
      "https://animusedu.com/wp-content/uploads/2023/02/photo_2023-02-07_20-20-21-1024x768.jpg",
      "https://animusedu.com/wp-content/uploads/2023/02/photo_2023-02-07_20-20-24-1024x768.jpg"
    ],
    "summary": "Animus Foundation together with partnersLinkuva Youth & Children CentreandAsociace Cesta rozvojeproud to present a series of podcasts created by young people from the Czech Republic, Lithuania, and Poland.",
    "text_blocks": [
      "Animus Foundation together with partnersLinkuva Youth & Children CentreandAsociace Cesta rozvojeproud to present a series of podcasts created by young people from the Czech Republic, Lithuania, and Poland.",
      "Within the framework of the Youth in Action project, a youth exchange was held in Biały Dunajec. Young people from among the volunteers gathered to discuss volunteering and the neighborhood.",
      "The main theme of the podcasts is the experiences related to volunteering. Listeners can also hear tips on how to start volunteering and useful information once they are already a volunteer. The podcasts are very interesting as the young people created them in international groups, which often led to interesting exchanges of ideas and opinions.",
      "We encourage you to listen to the first two podcasts on Spotify:",
      "Link to the podcasts here",
      "More will be added in the near future, so follow our page for information on their addition. Share this information with your friends and let us know what you think of the podcasts.",
      "#Volunteerneighbor  #Volunteeringintheneighborhood #startvoluntering #helpyourneighborhood #volunteering #neigborhood"
    ],
    "h1s": [
      "Volunteer Podcasts from the Source"
    ],
